"""QQ-Lora分组加载 的缩略图路由：把 LoRA 同名预览图发给前端。

查找顺序（都在 loras 目录内，文件名大小写不敏感）：

1. ``foo.safetensors.preview.png``
2. ``foo.preview.png``
3. ``foo.safetensors.png`` / ``foo.png``
4. ``previews/loras/foo.safetensors.preview.png`` 等

支持 png / jpg / jpeg / webp / gif。找不到就返回 404，前端据此不显示预览。
"""

from __future__ import annotations

import os
import time
from pathlib import Path

PREVIEW_EXTENSIONS = (".png", ".jpg", ".jpeg", ".webp", ".gif")
PREVIEW_SUFFIXES = (".preview", "")
MIME_TYPES = {
    ".png": "image/png",
    ".jpg": "image/jpeg",
    ".jpeg": "image/jpeg",
    ".webp": "image/webp",
    ".gif": "image/gif",
}
#: 同一个 LoRA 的查找结果缓存多久（秒）；新放进去的预览图最多这么久后可见。
CACHE_TTL = 30.0

_cache: dict[str, tuple[float, str | None]] = {}


def _loras_root() -> Path | None:
    try:
        import folder_paths

        return Path(folder_paths.get_folder_paths("loras")[0])
    except Exception:
        return None


def _candidates(model_path: Path) -> list[Path]:
    stem = model_path.with_suffix("") if model_path.suffix else model_path
    names: list[str] = []
    for base in (model_path.name, stem.name):
        for suffix in PREVIEW_SUFFIXES:
            for extension in PREVIEW_EXTENSIONS:
                names.append(base + suffix + extension)
    directory = model_path.parent
    found = []
    try:
        existing = {entry.name.lower(): entry for entry in directory.iterdir() if entry.is_file()}
    except OSError:
        return []
    for name in names:
        entry = existing.get(name.lower())
        if entry is not None:
            found.append(entry)
    return found


def _previews_dir_candidates(model_path: Path) -> list[Path]:
    try:
        import folder_paths

        root = Path(folder_paths.get_previews_directory())
    except Exception:
        return []
    loras_root = _loras_root()
    if loras_root is None:
        return []
    try:
        relative = model_path.relative_to(loras_root)
    except ValueError:
        return []
    stem = relative.with_suffix("") if relative.suffix else relative
    found = []
    for base in (relative, stem):
        for suffix in PREVIEW_SUFFIXES:
            for extension in PREVIEW_EXTENSIONS:
                candidate = root / "loras" / Path(str(base) + suffix + extension)
                if candidate.is_file():
                    found.append(candidate)
    return found


def find_preview(name: str) -> Path | None:
    """给 LoRA 文件名（相对 loras 目录）找同目录/预览目录里的图片。"""
    text = str(name or "").strip()
    if not text:
        return None
    now = time.monotonic()
    cached = _cache.get(text)
    if cached and now - cached[0] < CACHE_TTL:
        return Path(cached[1]) if cached[1] else None

    result: Path | None = None
    try:
        import folder_paths

        model = folder_paths.get_full_path("loras", text)
    except Exception:
        model = None
    if model:
        model_path = Path(model)
        candidates = _candidates(model_path) or _previews_dir_candidates(model_path)
        if candidates:
            result = candidates[0]
    _cache[text] = (now, str(result) if result else None)
    return result


def preview_payload(name: str) -> tuple[bytes, str] | None:
    """读预览图内容；找不到返回 None（给测试和路由共用）。"""
    path = find_preview(name)
    if path is None or not path.is_file():
        return None
    try:
        return path.read_bytes(), MIME_TYPES.get(path.suffix.lower(), "application/octet-stream")
    except OSError:
        return None


def register() -> None:
    """挂到 PromptServer；没有 aiohttp/server 时静默跳过。"""
    try:
        from aiohttp import web
        from server import PromptServer
    except Exception:
        return
    server = getattr(PromptServer, "instance", None)
    routes = getattr(server, "routes", None) if server is not None else None
    if routes is None:
        return

    async def preview(request):
        name = request.query.get("name", "")
        payload = preview_payload(name)
        if payload is None:
            return web.json_response({"error": "not found"}, status=404)
        body, mime = payload
        return web.Response(body=body, content_type=mime, headers={"Cache-Control": "max-age=60"})

    try:
        routes.get("/qq_lora/preview")(preview)
    except Exception as err:  # 路由挂不上不影响节点
        print(f"[QQ-Lora分组加载] 预览路由未注册：{err}", flush=True)
